commits.content:
'use client';

interface Props {
  query: string;
  onQueryChange: (value: string) => void;
  resultCount: number;
  currentIndex: number;
  onPrev: () => void;
  onNext: () => void;
  onClear: () => void;
}

export default function SearchBar({
  query,
  onQueryChange,
  resultCount,
  currentIndex,
  onPrev,
  onNext,
  onClear,
}: Props) {
  return (
    <div className="border-b border-gray-800 px-4 py-2 flex items-center gap-2">
      {/* 搜索图标 */}
      <span className="text-gray-500 text-sm">🔍</span>

      {/* 搜索输入框 */}
      <input
        type="text"
        value={query}
        onChange={(e) => onQueryChange(e.target.value)}
        placeholder="搜索当前会话..."
        className="flex-1 bg-gray-800 border border-gray-700 rounded px-3 py-1 text-sm text-gray-200 focus:outline-none focus:border-blue-500"
        autoFocus
        onKeyDown={(e) => {
          if (e.key === 'Enter') onNext();
        }}
      />

      {/* 结果计数 */}
      {query && (
        <span className="text-xs text-gray-500 min-w-[60px] text-center">
          {resultCount > 0
            ? `${currentIndex + 1}/${resultCount}`
            : '无匹配'}
        </span>
      )}

      {/* 上下切换按钮 */}
      {resultCount > 0 && (
        <>
          <button
            onClick={onPrev}
            className="text-gray-400 hover:text-white text-sm px-1 transition"
            title="上一个"
          >
            ▲
          </button>
          <button
            onClick={onNext}
            className="text-gray-400 hover:text-white text-sm px-1 transition"
            title="下一个"
          >
            ▼
          </button>
        </>
      )}

      {/* 关闭按钮 */}
      {query && (
        <button
          onClick={onClear}
          className="text-gray-500 hover:text-gray-300 text-sm transition"
          title="关闭搜索"
        >
          ✕
        </button>
      )}
    </div>
  );
}
